import { Howl, Howler } from 'howler'

/**
 * Every sound on the site lives here, so components ask for a sound by name
 * instead of each creating their own Howl. Files are generated by
 * `npm run assets` (scripts/generate-assets.mjs).
 */
const SOUND_DEFS = {
  hover: { file: 'ui-hover', volume: 0.35 },
  hoverOut: { file: 'ui-hover-out', volume: 0.2 },
  click: { file: 'ui-click', volume: 0.5 },
  menuOpen: { file: 'menu-open', volume: 0.55 },
  menuClose: { file: 'menu-close', volume: 0.45 },
  decode: { file: 'decode', volume: 0.18 },
  intro: { file: 'intro', volume: 0.7 },
  ambient: { file: 'ambient-loop', volume: 0.32, loop: true },
} as const

export type SoundName = keyof typeof SOUND_DEFS

const sounds = new Map<SoundName, Howl>()
let lastPlayed: Partial<Record<SoundName, number>> = {}

/** Creates every Howl and resolves once each has loaded (or failed). */
export function loadSounds(report: (p: number) => void) {
  const names = Object.keys(SOUND_DEFS) as SoundName[]
  let done = 0
  return Promise.all(
    names.map(
      (name) =>
        new Promise<void>((resolve) => {
          const def = SOUND_DEFS[name]
          const howl = new Howl({
            src: [`/audio/${def.file}.wav`],
            volume: def.volume,
            loop: 'loop' in def ? def.loop : false,
            preload: true,
          })
          const finish = () => {
            report(++done / names.length)
            resolve()
          }
          howl.once('load', finish)
          howl.once('loaderror', finish)
          sounds.set(name, howl)
        }),
    ),
  )
}

/**
 * Plays a sound. `throttleMs` stops rapid re-triggers (e.g. sweeping the
 * cursor across a row of links) from stacking into noise.
 */
export function playSound(name: SoundName, { throttleMs = 60, rate }: { throttleMs?: number; rate?: number } = {}) {
  const howl = sounds.get(name)
  if (!howl) return
  const now = performance.now()
  if (now - (lastPlayed[name] ?? 0) < throttleMs) return
  lastPlayed[name] = now
  const id = howl.play()
  if (rate) howl.rate(rate, id)
}

export function stopSound(name: SoundName) {
  sounds.get(name)?.stop()
}

export function fadeSound(name: SoundName, to: number, ms = 800) {
  const howl = sounds.get(name)
  if (!howl) return
  if (!howl.playing()) {
    howl.volume(0)
    howl.play()
  }
  howl.fade(howl.volume(), to, ms)
}

/** One switch for every sound, like a hardware mute. */
export function setMuted(muted: boolean) {
  Howler.mute(muted)
}

/** Browsers block audio until a user gesture; call this from a click. */
export async function unlockAudio() {
  const ctx = Howler.ctx
  if (ctx && ctx.state !== 'running') await ctx.resume()
}

export function resetSoundThrottle() {
  lastPlayed = {}
}
